// Upstream 1.4.1/1.4.4 Android assets 404; v1.4.2 publishes the .so zips.
def duckDbRelease = 'v1.4.2'
def zipFiles = [
    'arm64-v8a': "https://github.com/TigerEyeLabs/duckdb-dart/releases/download/${duckDbRelease}/libduckdb-android_arm64-v8a.zip",
    'armeabi-v7a': "https://github.com/TigerEyeLabs/duckdb-dart/releases/download/${duckDbRelease}/libduckdb-android_armeabi-v7a.zip"
]

task downloadAndExtractDuckDB {
    doLast {
        zipFiles.each { abi, url ->
            def libDir = file("$jniLibsDir/$abi")
            def libFile = file("$libDir/libduckdb.so")
            if (!libFile.exists()) {
                def tmpDir = file("$buildDir/tmp")
                tmpDir.mkdirs()
                def zipFile = file("$tmpDir/duckdb-${abi}.zip")

                // Ensure the jniLibs directory for this ABI exists
                libDir.mkdirs()

                // Download the zip file (fail clearly on HTTP errors / tiny 404 bodies)
                println "Downloading $url"
                def connection = new URL(url).openConnection()
                connection.instanceFollowRedirects = true
                def code = connection.responseCode
                if (code != 200) {
                    throw new GradleException("Failed to download DuckDB for $abi: HTTP $code from $url")
                }
                connection.inputStream.withStream { i ->
                    zipFile.withOutputStream { it << i }
                }
                if (zipFile.length() < 1024) {
                    throw new GradleException("DuckDB download for $abi looks invalid (${zipFile.length()} bytes): $url")
                }

                // Extract the zip file
                println "Extracting to $libDir"
                copy {
                    from zipTree(zipFile)
                    into libDir
                    include "*.so"
                }

                // Clean up the zip file
                delete zipFile

                if (!libFile.exists()) {
                    throw new GradleException("libduckdb.so missing after extract for $abi")
                }
            } else {
                println "Library for $abi already exists, skipping download"
            }
        }
    }
}

